  },
];

function PuppyImage({ src, alt, className = '' }) {
  return (
    <img
      src={src || FALLBACK_IMAGE}
      alt={alt}
      className={className}
      loading="lazy"
      onError={(event) => {
        event.currentTarget.onerror = null;
        event.currentTarget.src = FALLBACK_IMAGE;
      }}
    />
  );
}

export default function PuppiesView({
  puppies = [],
  activeFilters,
  updateFilter,
  showPuppyDetail,
  setCurrentView,
}) {
  const filters = activeFilters || {
    where: 'Everywhere',
    breeds: [],
    genders: [],
  };

  const filteredPuppies = puppies.filter((puppy) => {
    const matchWhere =
      filters.where === 'Everywhere' ||
      puppy.where === filters.where;

    const matchBreed =
      filters.breeds.length === 0 ||
      filters.breeds.includes(puppy.breed);

    const matchGender =
      filters.genders.length === 0 ||
      filters.genders.includes(puppy.gender);

    return matchWhere && matchBreed && matchGender;
  });

  const isBtnActive = (type, value) => {
    if (type === 'where') {
      return filters.where === value;
    }

    if (type === 'breed') {
      return filters.breeds.includes(value);
    }

    if (type === 'gender') {
      return filters.genders.includes(value);
    }

    return false;
  };

  return (
    <main className="fade-in puppies-container">
      <h2>Available puppies</h2>

      <p className="puppies-desc">
        Every listing shows photos of the puppy. Open a profile
        to see more details, then contact us on WhatsApp.
      </p>

      {/* LOCATION FILTER */}
      <div className="filters-box">
        <div className="filter-row">
          <span className="filter-label">Where</span>

          <div className="filter-btns">
            {[
              'Everywhere',
              'Imported',
              'Korean Teacup',
              'Dubai',
            ].map((location) => (
              <button
                key={location}
                type="button"
                onClick={() => updateFilter('where', location)}
                className={`filter-btn ${
                  isBtnActive('where', location) ? 'active' : ''
                }`}
              >
                {location}
              </button>
            ))}
          </div>
        </div>

        {/* BREED FILTER */}
        <div className="filter-row">
          <span className="filter-label">Breed</span>

          <div className="filter-btns">
            {[
              'Maltipoo',
              'Pomeranian',
              'Poodle',
              'Cavapoo',
              'Shih Tzu',
            ].map((breed) => (
              <button
                key={breed}
                type="button"
                onClick={() => updateFilter('breed', breed)}
                className={`filter-btn ${
                  isBtnActive('breed', breed) ? 'active' : ''
                }`}
              >
                {breed}
              </button>
            ))}
          </div>
        </div>

        {/* GENDER FILTER */}
        <div className="filter-row">
          <span className="filter-label">Boy or girl</span>

          <div className="filter-btns">
            {['Boy', 'Girl'].map((gender) => (
              <button
                key={gender}
                type="button"
                onClick={() => updateFilter('gender', gender)}
                className={`filter-btn ${
                  isBtnActive('gender', gender) ? 'active' : ''
                }`}
              >
                {gender}s
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* PUPPY COUNT */}
      <p className="puppy-count">
        <span>{filteredPuppies.length}</span> puppies looking for a home
      </p>

      {/* AVAILABLE PUPPY CARDS */}
      {filteredPuppies.length === 0 ? (
        <div className="empty-state">
          No puppies match your filters. Try selecting another breed
          or location.
        </div>
      ) : (
        <div className="puppy-grid">
          {filteredPuppies.map((puppy) => (
            <button
              key={puppy.id || puppy._id}
              type="button"
              onClick={() =>
                showPuppyDetail(puppy.id || puppy._id)
              }
              className="puppy-card"
              aria-label={`View ${puppy.name}, ${puppy.breed}`}
            >
              <div className="pc-image-wrapper">
                <div
                  className="pc-bg"
                  style={{
                    backgroundColor: puppy.colorBg || '#f8f1e9',
                  }}
                />

                <div className="pc-badge">🐾 Available</div>

                <div className="pc-img-container">
                  <PuppyImage
                    src={puppy.image}
                    alt={`${puppy.breed || 'Puppy'} - ${puppy.name || ''}`}
                    className="puppy-image"
                  />
                </div>
              </div>

              <h3 className="pc-name font-serif">
                {puppy.name || 'Puppy'}
              </h3>

              <p className="pc-breed-gender">
                {puppy.breed || 'Breed not specified'} •{' '}
                {puppy.gender || 'Not specified'}
              </p>

              <p className="pc-meta">
                {puppy.where || 'Location not specified'} •{' '}
                {puppy.age || 'Age not specified'}
              </p>
            </button>
          ))}
        </div>
      )}

      {/* ALREADY GONE HOME SECTION */}
      <section className="gh-banner">
        <div className="gh-banner-text">
          <h2
            className="font-serif"
            style={{
              fontSize: 'clamp(2rem, 5vw, 3.5rem)',
              marginBottom: '0.5rem',
              lineHeight: '1.1',
            }}
          >
            Already gone home
          </h2>

          <p
            style={{
              fontSize: '1.125rem',
              marginBottom: '1.5rem',
              color: 'rgba(74, 59, 50, 0.8)',
            }}
          >
            These puppies have found their families.
          </p>

          <button
            type="button"
            className="btn-primary"
            onClick={() => setCurrentView('gone-home')}
          >
            See the puppies who&apos;ve gone home
          </button>
        </div>

        <div className="gh-banner-img-row">
          {GONE_HOME_PUPPIES.map((puppy) => (
            <div className="gh-circle-wrap" key={puppy.name}>
              <PuppyImage
                src={puppy.image}
                alt={`${puppy.name} puppy`}
                className="gh-circle"
              />

              <span className="gh-badge">gone home ♥</span>
              <span className="gh-name">{puppy.name}</span>
            </div>
          ))}
        </div>
      </section>
    </main>
  );
}
